//! Hachi's ring-switching reduction (ePrint 2026/156, §4.3, Fig. 7).
//!
//! This module does not accept a PCS opening. It reduces its public linear
//! relation to a typed opening obligation on the *same* commitment.
//! The transcript below is a domain-separated SHAKE256 instantiation, not
//! the authors' experimental prototype wire format. No security parameters
//! or lattice commitment are generated by this module.

use ark_ff::{Field, PrimeField};
use ark_serialize::CanonicalSerialize;
use lattirust_arithmetic::{
    challenge_set::labrador_exact_challenge_set::LabradorUniformPrime, traits::FromRandomBytes,
};
use sha3::{
    digest::{ExtendableOutput, Update, XofReader},
    Shake256,
};
use thiserror::Error;

#[derive(Clone, Copy, Debug, Error, PartialEq, Eq)]
pub enum HachiError {
    #[error("invalid Hachi parameters or public relation")]
    Shape,
    #[error("invalid Hachi proof shape")]
    ProofShape,
    #[error("sumcheck round does not match its predecessor")]
    SumcheckRound,
    #[error("sumcheck endpoint does not satisfy the reduced relation")]
    Endpoint,
    #[error("the line does not connect the two sumcheck opening claims")]
    Line,
    #[error("canonical transcript serialization failed")]
    Serialization,
    #[error("too many rejected transcript samples")]
    Sampling,
}

/// Public system Mz=y over Fp[X]/(X^d+1).
///
/// Polynomials are coefficient vectors, low degree first, padded implicitly
/// by zeros. Matrix rows have the same length. The auxiliary table contains
/// the columns z followed by quotient digits (row-major by equation, then by
/// least-significant gadget digit). The latter use radix `base`.
#[derive(Clone, Debug, PartialEq)]
pub struct LinearStatement<P> {
    pub ring_degree: usize,
    pub base: u64,
    pub matrix: Vec<Vec<Vec<P>>>,
    pub rhs: Vec<Vec<P>>,
}

/// One sumcheck argument. A round's entries are monomial coefficients
/// including the leading zero coefficients (fixed shape).
#[derive(Clone, Debug, PartialEq)]
pub struct Sumcheck<F> {
    pub rounds: Vec<Vec<F>>,
    pub endpoint: F,
}

/// Fig. 7 proof prefix. The two sumchecks are run sequentially, starting with
/// smallness. Their opening requests are combined on an affine line; see
/// [`reduce_linear_relation`].
#[derive(Clone, Debug, PartialEq)]
pub struct LinearProof<F, C> {
    pub commitment: C,
    pub smallness: Sumcheck<F>,
    pub relation: Sumcheck<F>,
    pub line: Vec<F>,
}

/// Not a verification result. The exact evaluation must still be verified
/// against the same commitment, on the indicated full dyadic table, with a
/// compatible commitment opening argument and security parameters.
#[must_use = "the final opening must be verified against this obligation"]
#[derive(Clone, Debug, PartialEq)]
pub struct FinalOpening<F, C> {
    commitment: C,
    point: Vec<F>,
    value: F,
    context: [u8; 32],
    word_log_degree: usize,
    coefficient_log_degree: usize,
    active_words: usize,
    coefficient_bound: u64,
}

impl<F: Copy, C> FinalOpening<F, C> {
    pub fn commitment(&self) -> &C {
        &self.commitment
    }

    /// Word coordinates followed by coefficient coordinates. The first
    /// coordinate of either part indexes the most-significant bit.
    pub fn point(&self) -> &[F] {
        &self.point
    }

    pub fn value(&self) -> F {
        self.value
    }

    /// Digest of the checked prefix for continuation domain separation.
    pub fn context(&self) -> &[u8; 32] {
        &self.context
    }

    pub fn word_log_degree(&self) -> usize {
        self.word_log_degree
    }

    pub fn coefficient_log_degree(&self) -> usize {
        self.coefficient_log_degree
    }

    /// Number of used words. Padding is still part of the full committed
    /// domain and range-checked, but does not enter the linear equations.
    pub fn active_words(&self) -> usize {
        self.active_words
    }

    pub fn coefficient_bound(&self) -> u64 {
        self.coefficient_bound
    }
}

struct Shape {
    words: usize,
    digits: usize,
    active_words: usize,
    word_bits: usize,
    coeff_bits: usize,
    row_bits: usize,
    small_degree: usize,
}

fn bits_for(n: usize) -> Result<usize, HachiError> {
    Ok(n.checked_next_power_of_two()
        .ok_or(HachiError::Shape)?
        .ilog2() as usize)
}

impl<P: PrimeField> LinearStatement<P> {
    fn shape(&self) -> Result<Shape, HachiError> {
        let d = self.ring_degree;
        // Runtime and range polynomial degree are controlled by parameters,
        // not the proof. The implementation supports small gadget bases.
        if !d.is_power_of_two() || !self.base.is_power_of_two() || !(2..=256).contains(&self.base) {
            return Err(HachiError::Shape);
        }
        if P::MODULUS <= (2 * self.base - 2).into() {
            return Err(HachiError::Shape);
        }
        let words = self.matrix.first().map_or(0, Vec::len);
        if words == 0
            || self.rhs.len() != self.matrix.len()
            || self.rhs.iter().any(|p| p.len() > d)
            || self
                .matrix
                .iter()
                .any(|row| row.len() != words || row.iter().any(|p| p.len() > d))
        {
            return Err(HachiError::Shape);
        }
        // ceil(log_base p) rounded up using the modulus bit length. Unsigned
        // digit decompositions fit [-base+1,base-1], as do balanced ones.
        let base_bits = self.base.ilog2() as usize;
        let digits = (P::MODULUS_BIT_SIZE as usize).div_ceil(base_bits);
        let active_words = self
            .matrix
            .len()
            .checked_mul(digits)
            .and_then(|x| x.checked_add(words))
            .ok_or(HachiError::Shape)?;
        let word_bits = bits_for(active_words)?;
        let coeff_bits = d.ilog2() as usize;
        d.checked_mul(1usize << word_bits)
            .ok_or(HachiError::Shape)?;
        Ok(Shape {
            words,
            digits,
            active_words,
            word_bits,
            coeff_bits,
            row_bits: bits_for(self.rhs.len())?,
            small_degree: 2 * self.base as usize,
        })
    }

    fn bind(&self, t: &mut Transcript) -> Result<(), HachiError> {
        t.usize(b"ring-degree", self.ring_degree);
        t.bytes(b"gadget-base", &self.base.to_le_bytes());
        t.canonical(b"M", &self.matrix)?;
        t.canonical(b"y", &self.rhs)
    }

    /// Number of quotient digits used per equation (see module description).
    pub fn quotient_digits(&self) -> Result<usize, HachiError> {
        Ok(self.shape()?.digits)
    }
}

struct Transcript(Shake256);

impl Transcript {
    fn new(context: &[u8]) -> Self {
        let mut t = Self(Shake256::default());
        t.bytes(b"protocol", b"lattirust/hachi-shake256/v3");
        t.bytes(b"context", context);
        t
    }

    fn bytes(&mut self, label: &[u8], bytes: &[u8]) {
        self.0.update(&(label.len() as u64).to_le_bytes());
        self.0.update(label);
        self.0.update(&(bytes.len() as u64).to_le_bytes());
        self.0.update(bytes);
    }

    fn usize(&mut self, label: &[u8], n: usize) {
        self.bytes(label, &(n as u64).to_le_bytes());
    }

    fn canonical<T: CanonicalSerialize>(
        &mut self,
        label: &[u8],
        value: &T,
    ) -> Result<(), HachiError> {
        let mut bytes = Vec::with_capacity(value.compressed_size());
        value
            .serialize_compressed(&mut bytes)
            .map_err(|_| HachiError::Serialization)?;
        self.bytes(label, &bytes);
        Ok(())
    }

    fn field_context<F: Field>(&mut self) {
        use ark_ff::BigInteger;
        self.bytes(b"prime-modulus", &F::BasePrimeField::MODULUS.to_bytes_le());
        self.bytes(b"extension-degree", &F::extension_degree().to_le_bytes());
    }

    fn reader(&mut self, label: &[u8]) -> impl XofReader + use<> {
        self.bytes(b"challenge", label);
        self.0.clone().finalize_xof()
    }

    fn field<F: Field>(&mut self, label: &[u8]) -> Result<F, HachiError> {
        fn prime<P: PrimeField>(r: &mut impl XofReader) -> Result<P, HachiError> {
            let mut bytes = vec![0; LabradorUniformPrime::<P>::byte_size()];
            r.read(&mut bytes);
            LabradorUniformPrime::<P>::try_from_random_bytes(&bytes).ok_or(HachiError::Sampling)
        }
        let mut r = self.reader(label);
        let elems = (0..F::extension_degree())
            .map(|_| prime::<F::BasePrimeField>(&mut r))
            .collect::<Result<Vec<_>, _>>()?;
        let out = F::from_base_prime_field_elems(elems).ok_or(HachiError::Sampling)?;
        self.canonical(b"sample", &out)?;
        Ok(out)
    }

    fn fields<F: Field>(&mut self, label: &[u8], n: usize) -> Result<Vec<F>, HachiError> {
        (0..n).map(|_| self.field(label)).collect()
    }

    fn sparse<P: PrimeField>(
        &mut self,
        degree: usize,
        weight: usize,
    ) -> Result<Vec<P>, HachiError> {
        let mut r = self.reader(b"fold-challenge");
        let mut positions: Vec<_> = (0..degree).collect();
        let mut polynomial = vec![P::ZERO; degree];
        let mut encoding = Vec::with_capacity(weight * 9);
        for j in 0..weight {
            let count = (degree - j) as u64;
            // Uniform reduction of 64-bit words, including for non-dyadic
            // numbers of remaining positions.
            let reject_below = count.wrapping_neg() % count;
            let mut bytes = [0u8; 33];
            r.read(&mut bytes);
            let index = bytes[..32]
                .chunks_exact(8)
                .find_map(|chunk| {
                    let n = u64::from_le_bytes(chunk.try_into().ok()?);
                    (n >= reject_below).then(|| j + (n % count) as usize)
                })
                .ok_or(HachiError::Sampling)?;
            positions.swap(j, index);
            let sign = bytes[32] & 1;
            let position = positions[j];
            polynomial[position] = if sign == 0 { P::ONE } else { -P::ONE };
            encoding.extend_from_slice(&(position as u64).to_le_bytes());
            encoding.push(sign);
        }
        self.bytes(b"sparse-sample", &encoding);
        Ok(polynomial)
    }

    fn digest(mut self) -> [u8; 32] {
        let mut out = [0; 32];
        self.reader(b"continue").read(&mut out);
        out
    }
}

fn eval<F: Field>(coeffs: &[F], x: F) -> F {
    coeffs.iter().rev().fold(F::ZERO, |v, &c| v * x + c)
}

fn eval_lift<F: Field>(coeffs: &[F::BasePrimeField], x: F) -> F {
    coeffs
        .iter()
        .rev()
        .fold(F::ZERO, |v, &c| v * x + F::from_base_prime_field(c))
}

fn weights<F: Field>(point: &[F]) -> Vec<F> {
    let mut result = vec![F::ONE];
    for &x in point {
        result = result
            .into_iter()
            .flat_map(|v| [v * (F::ONE - x), v * x])
            .collect();
    }
    result
}

fn eq<F: Field>(x: &[F], y: &[F]) -> F {
    x.iter()
        .zip(y)
        .map(|(&a, &b)| a * b + (F::ONE - a) * (F::ONE - b))
        .product()
}

fn range_poly<F: Field>(x: F, base: u64) -> F {
    (1..base).fold(x, |v, n| {
        let digit = F::from_base_prime_field(F::BasePrimeField::from(n));
        v * (x - digit) * (x + digit)
    })
}

fn sumcheck<F: Field>(
    t: &mut Transcript,
    tag: &[u8],
    proof: &Sumcheck<F>,
    n: usize,
    degree: usize,
    mut claim: F,
) -> Result<(Vec<F>, F), HachiError> {
    if proof.rounds.len() != n || proof.rounds.iter().any(|g| g.len() != degree + 1) {
        return Err(HachiError::ProofShape);
    }
    t.bytes(b"sumcheck", tag);
    let mut point = Vec::with_capacity(n);
    for g in &proof.rounds {
        if g[0] + g.iter().copied().sum::<F>() != claim {
            return Err(HachiError::SumcheckRound);
        }
        t.canonical(b"round", g)?;
        let x = t.field(b"sumcheck-evaluation")?;
        point.push(x);
        claim = eval(g, x);
    }
    t.canonical(b"endpoint", &proof.endpoint)?;
    Ok((point, claim))
}

// Contract only the rows of M_alpha, including the signed quotient
// gadget. The remaining table is a tensor product with [alpha^i]_i.
fn project_rows<F: Field>(
    statement: &LinearStatement<F::BasePrimeField>,
    shape: &Shape,
    alpha: F,
    row_weights: &[F],
) -> Vec<F> {
    let mut projected = vec![F::ZERO; shape.active_words];
    let radix = F::from_base_prime_field(F::BasePrimeField::from(statement.base));
    let wrap = alpha.pow([statement.ring_degree as u64]) + F::ONE;
    for (i, (row, &lambda)) in statement.matrix.iter().zip(row_weights).enumerate() {
        for (p, sum) in row.iter().zip(&mut projected) {
            if !p.is_empty() {
                *sum += lambda * eval_lift(p, alpha);
            }
        }
        let start = shape.words + i * shape.digits;
        let mut coeff = -lambda * wrap;
        for word in &mut projected[start..start + shape.digits] {
            *word = coeff;
            coeff *= radix;
        }
    }
    projected
}

// Evaluate the projected MLE at the actual sumcheck point without
// materializing the full padded coefficient table.
fn linear_endpoint<F: Field>(projected: &[F], shape: &Shape, alpha: F, point: &[F]) -> F {
    let (word_point, coeff_point) = point.split_at(shape.word_bits);
    let m: F = projected
        .iter()
        .zip(weights(word_point))
        .map(|(&a, b)| a * b)
        .sum();
    // [1, alpha, ..., alpha^(d-1)] is a tensor product. Coordinates
    // are in most-significant-bit order.
    let mut alpha_power = alpha;
    let mut alpha_mle = F::ONE;
    for &x in coeff_point.iter().rev() {
        alpha_mle *= F::ONE - x + x * alpha_power;
        alpha_power.square_in_place();
    }
    m * alpha_mle
}

/// Verify the Fig. 7 sumchecks for an externally supplied public ring-linear
/// relation, then return one final opening obligation. This standalone entry
/// point does not check that an external commitment has an opening before the
/// caller closes the returned obligation.
///
/// The two sumchecks end at generally different points. Let L(s) be the
/// affine line through those points. The coefficient vector of the alleged
/// restriction w(L(s)) (degree at most the number of variables) is bound
/// before sampling s. Its values at 0 and 1 must match the sumcheck endpoints.
/// The resulting opening authenticates both claims up to the line batching
/// soundness error, under a compatible opening extraction/binding guarantee.
pub fn reduce_linear_relation<F, C>(
    context: &[u8],
    statement: &LinearStatement<F::BasePrimeField>,
    proof: &LinearProof<F, C>,
) -> Result<FinalOpening<F, C>, HachiError>
where
    F: Field,
    C: CanonicalSerialize + Clone,
{
    reduce_linear(
        Transcript::new(context),
        statement,
        proof,
        LinearBinding::Standalone,
    )
}

#[derive(Clone, Copy)]
enum LinearBinding {
    Standalone,
    DerivedEq20,
}

impl LinearBinding {
    fn bind<P: PrimeField>(
        self,
        statement: &LinearStatement<P>,
        transcript: &mut Transcript,
    ) -> Result<(), HachiError> {
        match self {
            Self::Standalone => statement.bind(transcript),
            Self::DerivedEq20 => {
                transcript.bytes(b"linear-source", b"derived-eq20/v1");
                Ok(())
            }
        }
    }
}

fn reduce_linear<F, C>(
    mut t: Transcript,
    statement: &LinearStatement<F::BasePrimeField>,
    proof: &LinearProof<F, C>,
    binding: LinearBinding,
) -> Result<FinalOpening<F, C>, HachiError>
where
    F: Field,
    C: CanonicalSerialize + Clone,
{
    let shape = statement.shape()?;
    t.field_context::<F>();
    binding.bind(statement, &mut t)?;
    let n = shape.word_bits + shape.coeff_bits;
    if proof.line.len() != n + 1 {
        return Err(HachiError::ProofShape);
    }
    t.canonical(b"short-table-commitment", &proof.commitment)?;
    let alpha = t.field(b"ring-switch")?;
    let tau0 = t.fields::<F>(b"smallness-row", n)?;
    let tau1 = t.fields::<F>(b"relation-row", shape.row_bits)?;
    let (p, a) = sumcheck(
        &mut t,
        b"smallness",
        &proof.smallness,
        n,
        shape.small_degree,
        F::ZERO,
    )?;
    let pval = proof.smallness.endpoint;
    // Check smallness on all digits, including quotient digits and padding;
    // this is the coefficient-domain constraint in (23).
    if a != eq(&tau0, &p) * range_poly(pval, statement.base) {
        return Err(HachiError::Endpoint);
    }
    let row_weights = weights(&tau1);
    let initial_claim = statement
        .rhs
        .iter()
        .zip(&row_weights)
        .map(|(poly, &w)| w * eval_lift(poly, alpha))
        .sum();
    let (q, b) = sumcheck(&mut t, b"relation", &proof.relation, n, 2, initial_claim)?;
    let qval = proof.relation.endpoint;
    let projected = project_rows(statement, &shape, alpha, &row_weights);
    if b != qval * linear_endpoint(&projected, &shape, alpha, &q) {
        return Err(HachiError::Endpoint);
    }
    if proof.line[0] != pval || proof.line.iter().copied().sum::<F>() != qval {
        return Err(HachiError::Line);
    }
    t.canonical(b"restriction-to-line", &proof.line)?;
    let s = t.field::<F>(b"line-point")?;
    let point = p.iter().zip(&q).map(|(&a, &b)| a + (b - a) * s).collect();
    Ok(FinalOpening {
        commitment: proof.commitment.clone(),
        point,
        value: eval(&proof.line, s),
        context: t.digest(),
        word_log_degree: shape.word_bits,
        coefficient_log_degree: shape.coeff_bits,
        active_words: shape.active_words,
        coefficient_bound: statement.base - 1,
    })
}

/// Fig. 3 public matrices A, B, D and decomposition parameters. These must
/// come from the trusted parameter/profile selection, not from an opening.
/// This type checks dimensions, not hardness or provenance of the matrices.
#[derive(Clone, Debug, PartialEq)]
pub struct FoldParams<P> {
    pub ring_degree: usize,
    pub base: u64,
    pub folded_digits: usize,
    pub challenge_weight: usize,
    pub a: Vec<Vec<Vec<P>>>,
    pub b: Vec<Vec<Vec<P>>>,
    pub d: Vec<Vec<Vec<P>>>,
}

/// The ring-valued evaluation claim of Eq. (15), after the input has been
/// reduced to a ring claim (e.g., the paper's separate §3 transformation).
#[derive(Clone, Debug, PartialEq)]
pub struct FoldStatement<P> {
    pub outer_commitment: Vec<Vec<P>>,
    pub value: Vec<P>,
    pub left: Vec<Vec<P>>,
    pub right: Vec<Vec<P>>,
}

/// Hachi Fig. 3 and Fig. 7 messages. The original short folded witness
/// is not revealed as in the explanatory Fig. 3.
#[derive(Clone, Debug, PartialEq)]
pub struct FoldProof<F: Field, C> {
    pub projected_commitment: Vec<Vec<F::BasePrimeField>>,
    pub linear: LinearProof<F, C>,
}

/// Verify a ring-valued Hachi reduction through Eq. (20) and Fig. 7.
/// Returns the still-unverified opening of the commitment to the short table.
/// The caller is responsible for verifying the original base-field claim's
/// reduction to the ring claim and ultimately satisfying this opening.
pub fn reduce_ring_opening<F, C>(
    context: &[u8],
    params: &FoldParams<F::BasePrimeField>,
    statement: &FoldStatement<F::BasePrimeField>,
    proof: &FoldProof<F, C>,
) -> Result<FinalOpening<F, C>, HachiError>
where
    F: Field,
    C: CanonicalSerialize + Clone,
{
    let (mut t, digits) = fold_transcript(context, params, statement, &proof.projected_commitment)?;
    let c = (0..statement.right.len())
        .map(|_| t.sparse(params.ring_degree, params.challenge_weight))
        .collect::<Result<Vec<_>, _>>()?;
    let linear = folded_relation(params, statement, &proof.projected_commitment, &c, digits)?;
    reduce_linear(t, &linear, &proof.linear, LinearBinding::DerivedEq20)
}

fn fold_shape<P: PrimeField>(p: &FoldParams<P>, l: usize, r: usize) -> Result<usize, HachiError> {
    let d = p.ring_degree;
    let nonempty_dyadic = |n: usize| n.is_power_of_two();
    if !nonempty_dyadic(d)
        || !nonempty_dyadic(l)
        || !nonempty_dyadic(r)
        || !p.base.is_power_of_two()
        || !(2..=256).contains(&p.base)
        || !(1..=d).contains(&p.challenge_weight)
        || p.folded_digits == 0
        || p.a.is_empty()
        || p.b.is_empty()
        || p.d.is_empty()
    {
        return Err(HachiError::Shape);
    }
    use ark_ff::BigInteger;
    let omega = p.challenge_weight as u64;
    let bound = omega
        .checked_mul(omega)
        .and_then(|s| s.checked_mul(8))
        .ok_or(HachiError::Shape)?;
    // Lemma 3 gives invertible differences between distinct short
    // challenges under these conditions. This is not a hardness estimator.
    if P::MODULUS.to_bytes_le()[0] & 7 != 5 || P::MODULUS <= bound.into() {
        return Err(HachiError::Shape);
    }
    let digits = (P::MODULUS_BIT_SIZE as usize).div_ceil(p.base.ilog2() as usize);
    if p.folded_digits > digits {
        return Err(HachiError::Shape);
    }
    let lw = l.checked_mul(digits).ok_or(HachiError::Shape)?;
    let rw = r.checked_mul(digits).ok_or(HachiError::Shape)?;
    let b_cols = rw.checked_mul(p.a.len()).ok_or(HachiError::Shape)?;
    let ring_vec_ok = |v: &[Vec<P>]| v.iter().all(|x| x.len() <= d);
    let matrix_ok = |m: &[Vec<Vec<P>>], n| m.iter().all(|row| row.len() == n && ring_vec_ok(row));
    if !matrix_ok(&p.a, lw) || !matrix_ok(&p.b, b_cols) || !matrix_ok(&p.d, rw) {
        return Err(HachiError::Shape);
    }
    Ok(digits)
}

fn fold_transcript<P: PrimeField>(
    context: &[u8],
    p: &FoldParams<P>,
    s: &FoldStatement<P>,
    v: &[Vec<P>],
) -> Result<(Transcript, usize), HachiError> {
    let d = p.ring_degree;
    let digits = fold_shape(p, s.left.len(), s.right.len())?;
    let ring_vec_ok = |v: &[Vec<P>]| v.iter().all(|x| x.len() <= d);
    if p.b.len() != s.outer_commitment.len()
        || p.d.len() != v.len()
        || !ring_vec_ok(&s.left)
        || !ring_vec_ok(&s.right)
        || !ring_vec_ok(&s.outer_commitment)
        || !ring_vec_ok(v)
        || s.value.len() > d
    {
        return Err(HachiError::Shape);
    }
    let mut t = Transcript::new(context);
    t.bytes(b"phase", b"split-and-fold");
    t.usize(b"ring-degree", d);
    t.bytes(b"gadget-base", &p.base.to_le_bytes());
    t.usize(b"folded-digits", p.folded_digits);
    t.usize(b"sparse-weight", p.challenge_weight);
    t.canonical(b"A", &p.a)?;
    t.canonical(b"B", &p.b)?;
    t.canonical(b"D", &p.d)?;
    t.canonical(b"outer-commitment", &s.outer_commitment)?;
    t.canonical(b"ring-value", &s.value)?;
    t.canonical(b"left", &s.left)?;
    t.canonical(b"right", &s.right)?;
    t.canonical(b"projected-commitment", &v.to_vec())?;
    Ok((t, digits))
}

/// Builds Eq. (20), in the column order (ŵ, t̂, ẑ). All entries are
/// polynomials modulo X^d+1; only multiplication by scalar gadget powers
/// occurs here. No MLE/cube is allocated in this step.
pub(crate) fn opening_geometry<P: PrimeField>(
    p: &FoldParams<P>,
    left: usize,
    right: usize,
) -> Result<(usize, usize), HachiError> {
    let digits = fold_shape(p, left, right)?;
    let width = right
        .checked_mul(digits)
        .and_then(|n| n.checked_mul(p.a.len().checked_add(1)?))
        .and_then(|n| n.checked_add(left.checked_mul(digits)?.checked_mul(p.folded_digits)?))
        .ok_or(HachiError::Shape)?;
    let equations =
        p.d.len()
            .checked_add(p.b.len())
            .and_then(|n| n.checked_add(p.a.len()))
            .and_then(|n| n.checked_add(2))
            .ok_or(HachiError::Shape)?;
    let active = equations
        .checked_mul(digits)
        .and_then(|n| n.checked_add(width))
        .ok_or(HachiError::Shape)?;
    let rounds = bits_for(active)?
        .checked_add(p.ring_degree.ilog2() as usize)
        .ok_or(HachiError::Shape)?;
    Ok((rounds, 2 * p.base as usize))
}

fn folded_relation<P: PrimeField>(
    p: &FoldParams<P>,
    s: &FoldStatement<P>,
    v: &[Vec<P>],
    c: &[Vec<P>],
    digits: usize,
) -> Result<LinearStatement<P>, HachiError> {
    let l = s.left.len();
    let r = s.right.len();
    let na = p.a.len();
    let w_end = r.checked_mul(digits).ok_or(HachiError::Shape)?;
    let t_end = w_end
        .checked_mul(na.checked_add(1).ok_or(HachiError::Shape)?)
        .ok_or(HachiError::Shape)?;
    let width = l
        .checked_mul(digits)
        .and_then(|n| n.checked_mul(p.folded_digits))
        .and_then(|n| n.checked_add(t_end))
        .ok_or(HachiError::Shape)?;
    let mut matrix = Vec::new();
    let mut rhs = Vec::new();
    let zero_row = || vec![Vec::new(); width];
    let radix = P::from(p.base);
    let gadget: Vec<_> = (0..(digits + p.folded_digits - 1))
        .scan(P::ONE, |power, _| {
            let cur = *power;
            *power *= radix;
            Some(cur)
        })
        .collect();
    let scale = |poly: &[P], k: P| {
        poly.iter()
            .map(|&coefficient| coefficient * k)
            .collect::<Vec<_>>()
    };
    for (row, y) in p.d.iter().zip(v) {
        let mut m = zero_row();
        m[..w_end].clone_from_slice(row);
        matrix.push(m);
        rhs.push(y.clone());
    }
    for (row, y) in p.b.iter().zip(&s.outer_commitment) {
        let mut m = zero_row();
        m[w_end..t_end].clone_from_slice(row);
        matrix.push(m);
        rhs.push(y.clone());
    }
    let mut m = zero_row();
    for (block, right) in m[..w_end].chunks_exact_mut(digits).zip(&s.right) {
        for (entry, &power) in block.iter_mut().zip(&gadget) {
            *entry = scale(right, power);
        }
    }
    matrix.push(m);
    rhs.push(s.value.clone());

    let mut m = zero_row();
    for (block, challenge) in m[..w_end].chunks_exact_mut(digits).zip(c) {
        for (entry, &power) in block.iter_mut().zip(&gadget) {
            *entry = scale(challenge, power);
        }
    }
    for (word, left) in s.left.iter().enumerate() {
        for j in 0..digits {
            for k in 0..p.folded_digits {
                m[t_end + (word * digits + j) * p.folded_digits + k] = scale(left, -gadget[j + k]);
            }
        }
    }
    matrix.push(m);
    rhs.push(Vec::new());

    for (i, a) in p.a.iter().enumerate() {
        let mut m = zero_row();
        for (j, challenge) in c.iter().enumerate() {
            for k in 0..digits {
                m[w_end + (j * na + i) * digits + k] = scale(challenge, gadget[k]);
            }
        }
        for (j, entry) in a.iter().enumerate() {
            for k in 0..p.folded_digits {
                m[t_end + j * p.folded_digits + k] = scale(entry, -gadget[k]);
            }
        }
        matrix.push(m);
        rhs.push(Vec::new());
    }
    Ok(LinearStatement {
        ring_degree: p.ring_degree,
        base: p.base,
        matrix,
        rhs,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use ark_ff::{AdditiveGroup, Fp64, MontBackend, MontConfig};

    #[derive(MontConfig)]
    #[modulus = "101"]
    #[generator = "2"]
    pub struct TestFieldConfig;
    type Fp = Fp64<MontBackend<TestFieldConfig, 1>>;

    fn fp(x: u64) -> Fp {
        Fp::from(x)
    }

    fn mle(table: &[Fp], point: &[Fp]) -> Fp {
        table.iter().zip(weights(point)).map(|(&v, w)| v * w).sum()
    }

    fn fixture_proof(
        t: Transcript,
        statement: &LinearStatement<Fp>,
        table: &[Fp],
    ) -> LinearProof<Fp, Vec<Fp>> {
        // Transparent test-only commitment of the entire table.
        prove_linear(
            t,
            statement,
            table,
            table.to_vec(),
            LinearBinding::Standalone,
        )
        .unwrap()
    }

    fn relation_fixture() -> (LinearStatement<Fp>, Vec<Fp>) {
        // (1+X) * X = (-1+X) + (X²+1) in the ordinary polynomial
        // ring, and X * X = -1 + (X²+1) for an independent row.
        let statement = LinearStatement {
            ring_degree: 2,
            base: 4,
            matrix: vec![vec![vec![Fp::ONE, Fp::ONE]], vec![vec![Fp::ZERO, Fp::ONE]]],
            rhs: vec![vec![-Fp::ONE, Fp::ONE], vec![-Fp::ONE]],
        };
        let words = vec![vec![Fp::ZERO, Fp::ONE]];
        let shape = statement.shape().unwrap();
        let table = prepare_linear_table(&statement, &words).unwrap();
        let mut expected = vec![Fp::ZERO; 1 << (shape.word_bits + shape.coeff_bits)];
        expected[1] = Fp::ONE;
        expected[2] = Fp::ONE;
        expected[2 * (1 + shape.digits)] = Fp::ONE;
        assert_eq!(table, expected);
        (statement, table)
    }

    #[test]
    fn honest_figure7_with_quotient_digits_hands_off_exact_table_opening() {
        let (statement, table) = relation_fixture();
        let context = b"quotient fixture";
        let proof = fixture_proof(Transcript::new(context), &statement, &table);
        let opening = reduce_linear_relation(context, &statement, &proof).unwrap();
        assert_eq!(opening.commitment(), &table);
        assert_eq!(opening.value(), mle(&table, opening.point()));
        assert_eq!(opening.coefficient_bound(), 3);
        assert_eq!(opening.coefficient_log_degree(), 1);
        assert_eq!(
            opening.active_words(),
            1 + 2 * statement.quotient_digits().unwrap()
        );
    }

    #[test]
    fn checks_round_shapes_equations_and_transcript_binding() {
        let (statement, table) = relation_fixture();
        let context = b"quotient fixture";
        let proof = fixture_proof(Transcript::new(context), &statement, &table);
        let mut changed = proof.clone();
        changed.relation.rounds[0].push(Fp::ZERO);
        assert_eq!(
            reduce_linear_relation(context, &statement, &changed).unwrap_err(),
            HachiError::ProofShape,
        );
        changed = proof.clone();
        changed.smallness.rounds[0][0] += Fp::ONE;
        assert_eq!(
            reduce_linear_relation(context, &statement, &changed).unwrap_err(),
            HachiError::SumcheckRound,
        );
        changed = proof.clone();
        changed.line[0] += Fp::ONE;
        assert_eq!(
            reduce_linear_relation(context, &statement, &changed).unwrap_err(),
            HachiError::Line,
        );
        changed = proof.clone();
        changed.commitment[0] += Fp::ONE;
        assert!(reduce_linear_relation(context, &statement, &changed).is_err());
        assert!(reduce_linear_relation(b"different context", &statement, &proof).is_err());
    }

    #[test]
    fn line_interior_is_only_authenticated_by_the_final_opening() {
        let (statement, table) = relation_fixture();
        let context = b"line fixture";
        let proof = fixture_proof(Transcript::new(context), &statement, &table);
        // Vanishes at 0 and 1 and does not itself falsify the sumchecks.
        // Test more than one nonzero coefficient to avoid the legitimate
        // probability that the Fiat-Shamir point is 0 or 1 in this tiny field.
        assert!((1..101).any(|delta| {
            let mut changed = proof.clone();
            changed.line[1] += fp(delta);
            changed.line[2] -= fp(delta);
            let opening = reduce_linear_relation(context, &statement, &changed).unwrap();
            opening.value() != mle(&table, opening.point())
        }));
    }

    #[test]
    fn eq20_uses_the_actual_transcript_fold_challenge() {
        let params = FoldParams {
            ring_degree: 2,
            base: 4,
            folded_digits: 1,
            challenge_weight: 1,
            a: vec![vec![vec![fp(2)], vec![], vec![], vec![]]],
            b: vec![vec![vec![fp(3)], vec![fp(12)], vec![], vec![]]],
            d: vec![vec![vec![fp(5)], vec![], vec![], vec![]]],
        };
        let input = vec![vec![vec![Fp::ONE]]];
        let u = commit_ring_reference(&params, &input).unwrap();
        assert_eq!(u, vec![vec![fp(6), Fp::ZERO]]);
        let statement = FoldStatement {
            outer_commitment: u,
            value: vec![Fp::ONE],
            left: vec![vec![Fp::ONE]],
            right: vec![vec![Fp::ONE]],
        };
        let context = b"Eq20 fixture";
        let (v, table) = prepare_fold(context, &params, &statement, &input).unwrap();
        assert_eq!(v, vec![vec![fp(5), Fp::ZERO]]);
        let c = folding_challenges(context, &params, &statement, &v).unwrap();
        let digits = 4;
        assert_eq!(table[0], Fp::ONE);
        // 2 decomposes as (-2) + 4, not as a single balanced digit.
        assert_eq!(table[digits * 2], -fp(2));
        assert_eq!(table[digits * 2 + 2], Fp::ONE);
        assert_eq!(&table[4 * digits..4 * digits + 2], c[0].as_slice());
        let proof =
            prove_ring_reference::<Fp, _>(context, &params, &statement, v, &table, table.clone())
                .unwrap();
        let opening = reduce_ring_opening(context, &params, &statement, &proof).unwrap();
        assert_eq!(opening.value(), mle(&table, opening.point()));
        let mut wrong_commitment = statement.clone();
        wrong_commitment.outer_commitment[0][0] += Fp::ONE;
        assert_eq!(
            prepare_fold(context, &params, &wrong_commitment, &input),
            Err(HachiError::Endpoint)
        );
        let mut changed = proof;
        changed.projected_commitment[0][0] += Fp::ONE;
        assert!(reduce_ring_opening(context, &params, &statement, &changed).is_err());
    }

    #[test]
    fn split_and_fold_nonconstant_two_by_two_table() {
        let matrix = |rows: u64, cols: u64, k: u64| {
            (0..rows)
                .map(|i| {
                    (0..cols)
                        .map(|j| vec![fp(i + k), fp(j + k + 1), fp(i * j + 2), fp(i + 2 * j + k)])
                        .collect()
                })
                .collect()
        };
        let params = FoldParams {
            ring_degree: 4,
            base: 4,
            folded_digits: 3,
            challenge_weight: 1,
            a: matrix(2, 8, 2),
            b: matrix(2, 16, 3),
            d: matrix(2, 8, 5),
        };
        let z = Fp::ZERO;
        let o = Fp::ONE;
        let input = vec![
            vec![vec![o, o], vec![z, z, fp(2)]],
            vec![vec![fp(3), z, z, -o], vec![o, o]],
        ];
        let statement = FoldStatement {
            outer_commitment: commit_ring_reference(&params, &input).unwrap(),
            value: vec![z, -fp(2), fp(3), fp(3)],
            left: vec![vec![z, z, z, o], vec![o, o]],
            right: vec![vec![o, -o], vec![z, z, o]],
        };
        let context = b"nonconstant 2x2";
        let (v, table) = prepare_fold(context, &params, &statement, &input).unwrap();
        let proof =
            prove_ring_reference::<Fp, _>(context, &params, &statement, v, &table, table.clone())
                .unwrap();
        let opening = reduce_ring_opening(context, &params, &statement, &proof).unwrap();
        assert_eq!(opening.value(), mle(&table, opening.point()));
        let mut wrong_value = statement;
        wrong_value.value[2] += o;
        assert_eq!(
            prepare_fold(context, &params, &wrong_value, &input),
            Err(HachiError::Endpoint)
        );
        assert!(reduce_ring_opening(context, &params, &wrong_value, &proof).is_err());
    }
}

/// Reference prover for the Fig. 7 reduction, not a PCS opening prover.
///
/// `table` is the entire dyadic word-by-coefficient Boolean table in
/// row-major order, including padding; its active entries correspond to the
/// original short words followed by short quotient digits. The caller must
/// construct `commitment` to that same table using the final opening scheme.
/// This routine neither checks that commitment nor emits its opening proof.
pub fn prove_linear_reference<F, C>(
    context: &[u8],
    statement: &LinearStatement<F::BasePrimeField>,
    table: &[F::BasePrimeField],
    commitment: C,
) -> Result<LinearProof<F, C>, HachiError>
where
    F: Field,
    C: CanonicalSerialize + Clone,
{
    prove_linear(
        Transcript::new(context),
        statement,
        table,
        commitment,
        LinearBinding::Standalone,
    )
}

/// Reference prover for an already constructed Fig. 3/7 short table. The
/// caller derives the table based on the context's actual folding challenge
/// before committing to it. This API serves the same reduction as
/// [`reduce_ring_opening`] and, like it, does not create a final PCS opening.
pub fn prove_ring_reference<F, C>(
    context: &[u8],
    params: &FoldParams<F::BasePrimeField>,
    statement: &FoldStatement<F::BasePrimeField>,
    projected_commitment: Vec<Vec<F::BasePrimeField>>,
    table: &[F::BasePrimeField],
    commitment: C,
) -> Result<FoldProof<F, C>, HachiError>
where
    F: Field,
    C: CanonicalSerialize + Clone,
{
    let (mut t, digits) = fold_transcript(context, params, statement, &projected_commitment)?;
    let c = (0..statement.right.len())
        .map(|_| t.sparse(params.ring_degree, params.challenge_weight))
        .collect::<Result<Vec<_>, _>>()?;
    let linear = folded_relation(params, statement, &projected_commitment, &c, digits)?;
    Ok(FoldProof {
        projected_commitment,
        linear: prove_linear(t, &linear, table, commitment, LinearBinding::DerivedEq20)?,
    })
}

/// Derive the same folding challenges as the verifier, to build a reference
/// prover table with Fig. 3. They are not proof inputs to the verifier.
pub fn folding_challenges<P: PrimeField>(
    context: &[u8],
    params: &FoldParams<P>,
    statement: &FoldStatement<P>,
    projected_commitment: &[Vec<P>],
) -> Result<Vec<Vec<P>>, HachiError> {
    let (mut t, _) = fold_transcript(context, params, statement, projected_commitment)?;
    (0..statement.right.len())
        .map(|_| t.sparse(params.ring_degree, params.challenge_weight))
        .collect()
}

// Standard interpolation at distinct prime field elements 0,...,degree.
// Public coefficients depend only on the profile, not the opening witness.
fn interpolation_basis<F: Field>(degree: usize) -> Result<Vec<Vec<F>>, HachiError> {
    (0..=degree)
        .map(|i| {
            let x = F::from(i as u64);
            let mut g = vec![F::ONE];
            let mut det = F::ONE;
            for j in (0..=degree).filter(|&j| j != i) {
                let y = F::from(j as u64);
                let mut next = vec![F::ZERO; g.len() + 1];
                for (k, &c) in g.iter().enumerate() {
                    next[k] -= y * c;
                    next[k + 1] += c;
                }
                g = next;
                det *= x - y;
            }
            let scale = det.inverse().ok_or(HachiError::Shape)?;
            g.iter_mut().for_each(|c| *c *= scale);
            Ok(g)
        })
        .collect()
}

fn interpolate<F: Field>(values: &[F], basis: &[Vec<F>]) -> Vec<F> {
    let mut out = vec![F::ZERO; values.len()];
    for (&a, g) in values.iter().zip(basis) {
        for (p, &b) in out.iter_mut().zip(g) {
            *p += a * b;
        }
    }
    out
}

fn fold_mle<F: Field>(table: &mut Vec<F>, x: F) {
    let half = table.len() / 2;
    for i in 0..half {
        let a = table[i];
        table[i] = a + (table[i + half] - a) * x;
    }
    table.truncate(half);
}

fn prove_sumcheck<F: Field>(
    t: &mut Transcript,
    tag: &[u8],
    degree: usize,
    mut witness: Vec<F>,
    mut public: Vec<F>,
    f: impl Fn(F) -> F,
    mut claim: F,
) -> Result<(Sumcheck<F>, Vec<F>), HachiError> {
    let basis = interpolation_basis(degree)?;
    t.bytes(b"sumcheck", tag);
    let mut point = Vec::new();
    let mut rounds = Vec::new();
    while witness.len() > 1 {
        let half = witness.len() / 2;
        let mut values = vec![F::ZERO; degree + 1];
        for j in 0..half {
            let mut w = witness[j];
            let dw = witness[j + half] - w;
            let mut p = public[j];
            let dp = public[j + half] - p;
            for v in &mut values {
                *v += p * f(w);
                w += dw;
                p += dp;
            }
        }
        if values[0] + values[1] != claim {
            return Err(HachiError::SumcheckRound);
        }
        let g = interpolate(&values, &basis);
        t.canonical(b"round", &g)?;
        let x = t.field(b"sumcheck-evaluation")?;
        claim = eval(&g, x);
        rounds.push(g);
        point.push(x);
        fold_mle(&mut witness, x);
        fold_mle(&mut public, x);
    }
    let endpoint = witness[0];
    if public[0] * f(endpoint) != claim {
        return Err(HachiError::Endpoint);
    }
    t.canonical(b"endpoint", &endpoint)?;
    Ok((Sumcheck { rounds, endpoint }, point))
}

fn prove_linear<F, C>(
    mut t: Transcript,
    statement: &LinearStatement<F::BasePrimeField>,
    witness: &[F::BasePrimeField],
    commitment: C,
    binding: LinearBinding,
) -> Result<LinearProof<F, C>, HachiError>
where
    F: Field,
    C: CanonicalSerialize + Clone,
{
    let shape = statement.shape()?;
    let n = shape.word_bits + shape.coeff_bits;
    if witness.len() != 1usize << n {
        return Err(HachiError::Shape);
    }
    t.field_context::<F>();
    binding.bind(statement, &mut t)?;
    t.canonical(b"short-table-commitment", &commitment)?;
    let alpha = t.field::<F>(b"ring-switch")?;
    let tau0 = t.fields::<F>(b"smallness-row", n)?;
    let tau1 = t.fields::<F>(b"relation-row", shape.row_bits)?;
    let w: Vec<_> = witness
        .iter()
        .copied()
        .map(F::from_base_prime_field)
        .collect();
    let (smallness, p) = prove_sumcheck(
        &mut t,
        b"smallness",
        shape.small_degree,
        w.clone(),
        weights(&tau0),
        |x| range_poly(x, statement.base),
        F::ZERO,
    )?;
    let row_weights = weights(&tau1);
    let claim = statement
        .rhs
        .iter()
        .zip(&row_weights)
        .map(|(poly, &weight)| weight * eval_lift(poly, alpha))
        .sum();
    let mut projected = project_rows(statement, &shape, alpha, &row_weights);
    projected.resize(1 << shape.word_bits, F::ZERO);
    let alpha_powers: Vec<_> = (0..statement.ring_degree)
        .scan(F::ONE, |power, _| {
            let old = *power;
            *power *= alpha;
            Some(old)
        })
        .collect();
    let m = projected
        .iter()
        .flat_map(|&v| alpha_powers.iter().map(move |&x| v * x))
        .collect();
    let (relation, q) = prove_sumcheck(&mut t, b"relation", 2, w.clone(), m, |x| x, claim)?;
    let basis = interpolation_basis(n)?;
    let values: Vec<_> = (0..=n)
        .map(|i| {
            let s = F::from(i as u64);
            let mut table = w.clone();
            for (&a, &b) in p.iter().zip(&q) {
                fold_mle(&mut table, a + (b - a) * s);
            }
            table[0]
        })
        .collect();
    Ok(LinearProof {
        commitment,
        smallness,
        relation,
        line: interpolate(&values, &basis),
    })
}

/// Decompose a coefficient into the paper's balanced radix digits
/// [-base/2,base/2-1]. Pick a centered representative when it fits, or
/// shift by exactly one modulus if required by the asymmetric interval.
/// This small reference helper supports prime moduli fitting 64 bits.
fn balanced<P: PrimeField>(x: P, base: u64, digits: usize) -> Option<Vec<P>> {
    use ark_ff::BigInteger;
    if P::MODULUS_BIT_SIZE > 64 {
        return None;
    }
    let low_u64 = |x: P::BigInt| {
        let b = x.to_bytes_le();
        u64::from_le_bytes(b[..8].try_into().expect("one full Arkworks limb"))
    };
    let q = i128::from(low_u64(P::MODULUS));
    let n = i128::from(low_u64(x.into_bigint()));
    let b = i128::from(base);
    let size = b.checked_pow(digits.try_into().ok()?)?;
    let offset = (size - 1) / (b - 1) * (b / 2);
    let mut centered = if n > q / 2 { n - q } else { n };
    if centered < -offset {
        centered += q;
    } else if centered >= size - offset {
        centered -= q;
    }
    let mut shifted = centered + offset;
    if !(0..size).contains(&shifted) {
        return None;
    }
    Some(
        (0..digits)
            .map(|_| {
                let digit = P::from((shifted % b - b / 2) as i64);
                shifted /= b;
                digit
            })
            .collect(),
    )
}

fn balanced_words<P: PrimeField>(
    poly: &[P],
    degree: usize,
    base: u64,
    digits: usize,
) -> Result<Vec<Vec<P>>, HachiError> {
    let mut output = vec![vec![P::ZERO; degree]; digits];
    for (i, &x) in poly.iter().enumerate() {
        for (dest, coeff) in output
            .iter_mut()
            .zip(balanced(x, base, digits).ok_or(HachiError::Shape)?)
        {
            dest[i] = coeff;
        }
    }
    Ok(output)
}

fn product_accumulate<P: PrimeField>(out: &mut [P], a: &[P], b: &[P], negacyclic: bool) {
    let n = out.len();
    for (i, &a_i) in a.iter().enumerate().filter(|(_, x)| **x != P::ZERO) {
        for (j, &b_j) in b.iter().enumerate().filter(|(_, x)| **x != P::ZERO) {
            let p = a_i * b_j;
            if negacyclic && i + j >= n {
                out[i + j - n] -= p;
            } else {
                out[i + j] += p;
            }
        }
    }
}

/// Prepare the exact short digit table in Eq. (21) from the given candidate
/// words `z`. Computes the ordinary-polynomial quotient for each row,
/// rejecting if the remainder is not `y`. Returns explicit dyadic padding.
/// This straightforward polynomial-arithmetic helper is intended as an
/// implementation oracle, not a production-performance prover.
pub fn prepare_linear_table<P: PrimeField>(
    statement: &LinearStatement<P>,
    words: &[Vec<P>],
) -> Result<Vec<P>, HachiError> {
    let shape = statement.shape()?;
    let d = statement.ring_degree;
    if words.len() != shape.words || words.iter().any(|p| p.len() > d) {
        return Err(HachiError::Shape);
    }
    // Both signs of every allowed coefficient are represented in Fp.
    let bound = P::from(statement.base - 1);
    let is_small =
        |x: P| x.into_bigint() <= bound.into_bigint() || (-x).into_bigint() <= bound.into_bigint();
    if !words.iter().flatten().copied().all(is_small) {
        return Err(HachiError::Endpoint);
    }
    let mut table = vec![P::ZERO; d * (1usize << shape.word_bits)];
    for (dest, w) in table.chunks_exact_mut(d).zip(words) {
        dest[..w.len()].copy_from_slice(w);
    }
    for (row_index, (row, rhs)) in statement.matrix.iter().zip(&statement.rhs).enumerate() {
        let mut product = vec![P::ZERO; 2 * d];
        for (a, b) in row.iter().zip(words) {
            product_accumulate(&mut product, a, b, false);
        }
        for (c, &y) in product.iter_mut().zip(rhs) {
            *c -= y;
        }
        let (low, high) = product.split_at(d);
        if low != high {
            return Err(HachiError::Endpoint);
        }
        let start = shape.words + row_index * shape.digits;
        let q = balanced_words(high, d, statement.base, shape.digits)?;
        for (offset, coeffs) in q.iter().enumerate() {
            let pos = (start + offset) * d;
            table[pos..pos + d].copy_from_slice(coeffs);
        }
    }
    Ok(table)
}

/// Return the projected commitment v and Fig. 7 table from the uncompressed
/// original ring-valued opening. `input` is in row-major order, with one row
/// for each right weight and one ring polynomial for each left weight.
///
/// As in the other reference prover helpers, the caller constructs the
/// actual final lattice commitment and proof for the returned table.
/// Products and decompositions here prioritize portability and auditability.
pub fn prepare_fold<P: PrimeField>(
    context: &[u8],
    p: &FoldParams<P>,
    s: &FoldStatement<P>,
    input: &[Vec<Vec<P>>],
) -> Result<(Vec<Vec<P>>, Vec<P>), HachiError> {
    let digits = fold_shape(p, s.left.len(), s.right.len())?;
    let d = p.ring_degree;
    if input.len() != s.right.len()
        || s.left.iter().any(|poly| poly.len() > d)
        || input
            .iter()
            .any(|row| row.len() != s.left.len() || row.iter().any(|poly| poly.len() > d))
    {
        return Err(HachiError::Shape);
    }
    let mut w_digits = Vec::new();
    let mut t_digits = Vec::new();
    let mut input_digits: Vec<Vec<Vec<P>>> = Vec::new();
    for row in input {
        let mut w = vec![P::ZERO; d];
        let mut decomposed = Vec::new();
        for (a, b) in s.left.iter().zip(row) {
            product_accumulate(&mut w, a, b, true);
            decomposed.extend(balanced_words(b, d, p.base, digits)?);
        }
        w_digits.extend(balanced_words(&w, d, p.base, digits)?);
        for a in &p.a {
            let mut t = vec![P::ZERO; d];
            for (entry, word) in a.iter().zip(&decomposed) {
                product_accumulate(&mut t, entry, word, true);
            }
            t_digits.extend(balanced_words(&t, d, p.base, digits)?);
        }
        input_digits.push(decomposed);
    }
    let v: Vec<_> =
        p.d.iter()
            .map(|row| {
                let mut v = vec![P::ZERO; d];
                for (a, w) in row.iter().zip(&w_digits) {
                    product_accumulate(&mut v, a, w, true);
                }
                v
            })
            .collect();
    let challenges = folding_challenges(context, p, s, &v)?;
    let mut folded = vec![vec![P::ZERO; d]; p.a[0].len()];
    for (challenge, row) in challenges.iter().zip(&input_digits) {
        for (z, w) in folded.iter_mut().zip(row) {
            product_accumulate(z, challenge, w, true);
        }
    }
    let linear = folded_relation(p, s, &v, &challenges, digits)?;
    let mut words = w_digits;
    words.extend(t_digits);
    for z in &folded {
        words.extend(balanced_words(z, d, p.base, p.folded_digits)?);
    }
    let table = prepare_linear_table(&linear, &words)?;
    Ok((v, table))
}

/// Reference inner-outer commitment of §4. `input` has one ring-polynomial
/// row per right coordinate, and one polynomial per left coordinate inside
/// each row. This ordinary Ajtai commitment is not statistically hiding.
/// The verifier must use independently selected, trusted parameters.
pub fn commit_ring_reference<P: PrimeField>(
    params: &FoldParams<P>,
    input: &[Vec<Vec<P>>],
) -> Result<Vec<Vec<P>>, HachiError> {
    let l = input.first().map_or(0, Vec::len);
    let digits = fold_shape(params, l, input.len())?;
    let d = params.ring_degree;
    if input
        .iter()
        .any(|row| row.len() != l || row.iter().any(|poly| poly.len() > d))
    {
        return Err(HachiError::Shape);
    }
    let mut inner = Vec::new();
    for row in input {
        let mut decomposed = Vec::new();
        for poly in row {
            decomposed.extend(balanced_words(poly, d, params.base, digits)?);
        }
        for a in &params.a {
            let mut t = vec![P::ZERO; d];
            for (entry, word) in a.iter().zip(&decomposed) {
                product_accumulate(&mut t, entry, word, true);
            }
            inner.extend(balanced_words(&t, d, params.base, digits)?);
        }
    }
    Ok(params
        .b
        .iter()
        .map(|row| {
            let mut u = vec![P::ZERO; d];
            for (a, b) in row.iter().zip(&inner) {
                product_accumulate(&mut u, a, b, true);
            }
            u
        })
        .collect())
}
